typescript_example:
// TypeScript (node-fetch / undici + Agent) example
import { RedwoodClient, TransportConfig } from '@redwood/inference';
import { Agent } from 'https';

const nodeAgent = new Agent({ keepAlive: true, maxSockets: 100, keepAliveMsecs: 90000 });
const cfg: TransportConfig = { connectTimeoutMs: 2000, readTimeoutMs: 60000, responseHeaderTimeoutMs: 5000, maxConns: 100, idleConnTimeoutMs: 90000, keepalive: true, maxRetries: 2, agent: nodeAgent };
const client = new RedwoodClient({ transportConfig: cfg });

// Streaming: use the SDK's streaming iterator; avoid global timeout if expecting long-lived streams
const stream = await client.streamCompletion({ model: 'x-large', prompt: '...' });
for await (const chunk of stream) {
  handle(chunk);
}

go_example:
// Go example (net/http Transport)
package sdkexamples

import (
  "net/http"
  "time"
  redwood "github.com/redwood-inference/sdk-go"
)

func Client() *redwood.Client {
  tr := &http.Transport{
    MaxIdleConns:        100,
    MaxIdleConnsPerHost: 10,
    IdleConnTimeout:     90 * time.Second,
    TLSHandshakeTimeout: 2 * time.Second,
    ExpectContinueTimeout: 1 * time.Second,
    // Go 1.18+: MaxConnsPerHost recommended for aggressive concurrency control
    MaxConnsPerHost: 100,
  }
  httpClient := &http.Client{
    Timeout: 60 * time.Second, // overall client timeout for non-streaming requests
    Transport: tr,
  }
  cfg := redwood.TransportConfig{ConnectTimeoutMs: 2000, ReadTimeoutMs: 60000, ResponseHeaderTimeoutMs: 5000, KeepAlive: true, MaxRetries: 2}
  return redwood.NewClient(redwood.ClientOptions{TransportConfig: cfg, HTTPClient: httpClient})
}
